from test_shared_sounds import test, tests

test('Pause immediately clears secure action and overrides without changing preferences', "local keys=table.concat(BuffTap.db.keys,','); local buffs=BuffTap.db.buffs; assert(BuffTap:PauseReminders(5)); assert(not BuffTap.action and not BuffTap.button.attrs.type1 and not next(bindings)); assert(BuffTap:ReminderPauseReason()=='temporary pause'); assert(BuffTap.db.enabled and BuffTap.db.buffs==buffs and table.concat(BuffTap.db.keys,',')==keys); assert(not BuffTap:PlayAlert('reminder')); assert(BuffTap:FriendlyStatus():find('5 min',1,true))")
test('Pause expires once and normal buffing resumes', "BuffTap:PauseReminders(5); advance(299); assert(not BuffTap.action); advance(2); assert(not BuffTap.pauseUntil and BuffTap.action and bindings.MOUSEWHEELDOWN)")
test('Repeated pause replacement retains one expiry timer', "BuffTap:PauseReminders(5); advance(20); BuffTap:PauseReminders(15); advance(281); assert(BuffTap:ReminderPauseReason()=='temporary pause'); assert(liveTimers()<=2); BuffTap:PauseReminders(0); assert(not BuffTap.pauseUntil and BuffTap.action and not BuffTap.timers['manual-pause'])")
test('Uncancellable After fallback cannot end a newer pause', "local nativeTimer=C_Timer.NewTimer; C_Timer.After=function(delay,fn) nativeTimer(delay,fn) end; C_Timer.NewTimer=nil; BuffTap:PauseReminders(5); advance(10); BuffTap:PauseReminders(15); advance(291); assert(BuffTap:ReminderPauseReason()=='temporary pause'); BuffTap:PauseReminders(0); advance(610); assert(not BuffTap.pauseUntil and BuffTap.action)")
test('Pause rejects malformed durations and combat mutations', "local keys=table.concat(BuffTap.db.keys,','); BuffTap:PauseReminders({}); assert(BuffTap.action and not BuffTap.pauseUntil); combat=true; safety('blocked'); assert(not BuffTap:PauseReminders(5)); assert(table.concat(BuffTap.db.keys,',')==keys)")
test('Pause expiry during combat defers secure restoration', "BuffTap:PauseReminders(5); combat=true; safety('blocked'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_REGEN_DISABLED'); advance(301); assert(not BuffTap.pauseUntil and not BuffTap.action and not BuffTap.button.attrs.type1); combat=false; safety('ready'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_REGEN_ENABLED'); assert(BuffTap.action)")
test('Quick controls toggle on right click and preview remains harmless', "BuffTap.minimapObject.OnClick(nil,'RightButton'); assert(BuffTap.quickMenu.shown); BuffTap.minimapObject.OnClick(nil,'RightButton'); assert(not BuffTap.quickMenu.shown); local id=BuffTap.action.id; BuffTap:PreviewAppearance(); assert(BuffTap.action.id==id and not BuffTap.appearancePreview.protected)")
test('First use is once per character and never changes buff choices', "local buffs=BuffTap.db.buffs; BuffTap:ScheduleWelcome(); advance(3); assert(BuffTap.welcome.shown and BuffTap.db.welcomeSeen and BuffTap.db.buffs==buffs); BuffTap.welcome:Hide(); BuffTap:ScheduleWelcome(); advance(3); assert(not BuffTap.welcome.shown); BuffTap:ShowWelcome(true); assert(BuffTap.welcome.shown)")
test('First use waits for a later login event if combat prevents it', "combat=true; BuffTap:ScheduleWelcome(); advance(3); assert(not BuffTap.db.welcomeSeen); combat=false; BuffTap:ScheduleWelcome(); advance(3); assert(BuffTap.welcome.shown)")
test('Unavailable Edit Mode is harmless and late manager hooks only once', "BuffTap:SyncEditMode(); assert(not BuffTap.editModeManager); local hooks={}; EditModeManagerFrame=CreateFrame('Frame'); EditModeManagerFrame.HookScript=function(_,k,fn) assert(not hooks[k]); hooks[k]=fn end; BuffTap:SyncEditMode(); BuffTap:SyncEditMode(); hooks.OnShow(); assert(BuffTap.editModeActive and BuffTap.editAnchor.shown and not BuffTap.editAnchor.protected and not BuffTap.action and not next(bindings)); hooks.OnHide(); assert(not BuffTap.editModeActive and not BuffTap.editAnchor.shown and BuffTap.action)")
test('Edit Mode drag saves shared position and never opens settings', "BuffTap:SetEditModeActive(true); BuffTap.editAnchor.GetCenter=function() return 610,620 end; BuffTap.editAnchor.scripts.OnDragStop(BuffTap.editAnchor); assert(BuffTap.db.x==110 and BuffTap.db.y==120 and not BuffTap.options); BuffTap:SetEditModeActive(false); assert(BuffTap.action)")
test('Edit Mode interruption cannot write protected frames', "BuffTap:SetEditModeActive(true); combat=true; safety('blocked'); BuffTap.editAnchor.scripts.OnEvent(BuffTap.editAnchor,'PLAYER_REGEN_DISABLED'); BuffTap:SetEditModeActive(false); assert(not BuffTap.editModeActive and not BuffTap.editAnchor.shown); combat=false; safety('ready'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_REGEN_ENABLED'); assert(BuffTap.action)")
test('Edit Mode preserves manual pause on exit', "BuffTap:PauseReminders(5); BuffTap:SetEditModeActive(true); BuffTap:SetEditModeActive(false); assert(not BuffTap.action and BuffTap.pauseUntil)")
test('Reminder styling applies to real labels and safe preview', "UNIT_NAME_FONT='valid-font.ttf'; BuffTap.db.labelFont='names'; BuffTap.db.labelColor='cyan'; local font,color; BuffTap.button.nameLabel.GetFont=function() return 'old',12,'OUTLINE' end; BuffTap.button.nameLabel.SetFont=function(_,p,size) font=p; assert(size==12) end; BuffTap.button.nameLabel.SetTextColor=function(_,r,g,b) color={r,g,b} end; refresh(); assert(font=='valid-font.ttf' and color[1]==.4 and color[3]==1); BuffTap:PreviewAppearance(); assert(BuffTap.appearancePreview.shown)")
test('Malformed style preferences normalize without touching binding', "BuffTap.db.labelFont={}; BuffTap.db.labelColor='bad'; BuffTap:InitDB(); assert(BuffTap.db.labelFont=='default' and BuffTap.db.labelColor=='default' and bindings.MOUSEWHEELDOWN); BuffTap:Options(); assert(BuffTap.options.fontButton.text=='Default font' and BuffTap.options.colorButton.text=='Text: default')")
test('Combat-delayed welcome resumes after combat', "combat=true; BuffTap:ScheduleWelcome(); advance(3); combat=false; BuffTap.events.scripts.OnEvent(nil,'PLAYER_REGEN_ENABLED'); advance(3); assert(BuffTap.welcome.shown)")
test('Reset look restores the default text style', "BuffTap.db.labelFont='names'; BuffTap.db.labelColor='gold'; BuffTap:Options(); assert(BuffTap.options.colorButton.text=='Text: gold'); BuffTap.options.resetLookButton.scripts.OnClick(); assert(BuffTap.db.labelFont=='default' and BuffTap.db.labelColor=='default' and BuffTap.options.colorButton.text=='Text: default')")
for locale in ['deDE','frFR','esES','ptBR']:
    test('Convenience localization '+locale, "BuffTap:ShowWelcome(true); assert(BuffTap.welcome.body.text:find('MOUSEWHEELDOWN',1,true)); assert(not BuffTap.welcome.body.text:find('Choose the buffs',1,true)); assert(BuffTap:Text('Resume reminders')~='Resume reminders'); BuffTap:PauseReminders(5); assert(not BuffTap:FriendlyStatus():find('Reminders paused',1,true))", locale=locale)
test('Closing Edit Mode mid-drag saves once without reopening settings', "BuffTap:SetEditModeActive(true); BuffTap.editAnchor.GetCenter=function() return 640,660 end; BuffTap.editAnchor.scripts.OnDragStart(BuffTap.editAnchor); BuffTap:SetEditModeActive(false); assert(BuffTap.db.x==140 and BuffTap.db.y==160 and not BuffTap.editAnchor.dragging and not BuffTap.options and BuffTap.action)")
test('Unavailable saved font remains visible and falls back safely', "BuffTap.db.labelFont='names'; UNIT_NAME_FONT=nil; BuffTap:Options(); assert(BuffTap.options.fontButton.text=='Unit-name font (unavailable)' and BuffTap.db.labelFont=='names'); refresh(); assert(BuffTap.action)")
print('ALL', len(tests), 'SCENARIOS PASSED')

